/**
 * i18n setup — French primary, Arabic and English secondary (T-388).
 *
 * Strings are kept inline (no JSON files) so the type checker verifies
 * every key exists at compile time. Translations are flat dotted keys
 * for predictable lookup.
 *
 * T-388: the `en` locale is a first-class citizen now, and every locale is
 * the deep merge of its HAND-MAINTAINED base dictionary (fr/ar/en.ts — the
 * curated keys) with its GENERATED dictionary (gen/fr|ar|en.ts — the ~2.8k
 * keys the codemod assigned to formerly hardcoded strings; regenerated by
 * scripts/i18n/apply-i18n.mjs dict, never edited by hand).
 *
 * T-583 (startup acceleration): only the FRENCH dictionary is bundled
 * eagerly (fr is the boot language — lng/fallbackLng). Arabic and English
 * load ON DEMAND through a tiny custom i18next backend: the first
 * `changeLanguage("ar"|"en")` (the language switcher / the preferences
 * provider) dynamic-imports the locale's dictionary modules and resolves
 * only once they are merged — every existing `await changeLanguage(...)`
 * call site keeps working unchanged (i18next awaits backend reads inside
 * changeLanguage). The ar/en chunks leave the eager entry bundle; the
 * dictionaries' CONTENT and the three-locale parity contract are
 * untouched (t-447 keeps proving resolution through t()).
 */
import i18next, { type BackendModule, type ReadCallback } from "i18next";
import { initReactI18next } from "react-i18next";
import { fr } from "./fr";
import { genFr } from "./gen/fr";
// T-447 (UI-325): the bilingual Statistics tooltip glossary — a
// self-contained module (compile-time locked to one shape across the
// three locales) merged into the same resources so every key resolves
// through the standard t() lookup. (T-583: FR stays eager — the boot
// language's glossary renders on the first Statistics screen without a
// round-trip; AR/EN ride their lazy dictionary chunks.)
import { STAT_TIPS_FR } from "./stats-tips";

type Dict = { [key: string]: string | Dict };

function deepMerge(base: Dict, extra: Dict): Dict {
  const out: Dict = { ...base };
  for (const [k, v] of Object.entries(extra)) {
    const b = out[k];
    out[k] =
      typeof b === "object" && b !== null && typeof v === "object" && v !== null
        ? deepMerge(b as Dict, v as Dict)
        : v;
  }
  return out;
}

/**
 * T-583: the on-demand locale backend. i18next calls `read` when a
 * language has no bundled resources; the dynamic import pulls the
 * locale's three dictionary modules (base + generated + glossary) as ONE
 * rollup chunk, deep-merges them exactly like the eager FR path, and
 * hands the merged tree back. `type: "backend"` + `init` no-op is the
 * whole of the i18next backend contract used here.
 */
const lazyLocaleBackend: BackendModule = {
  type: "backend",
  init: () => {},
  read: (language: string, _namespace: string, callback: ReadCallback) => {
    if (language === "ar") {
      void Promise.all([import("./ar"), import("./gen/ar"), import("./stats-tips")])
        .then(([{ ar }, { genAr }, { STAT_TIPS_AR }]) => {
          callback(
            null,
            deepMerge(deepMerge(ar as unknown as Dict, genAr as unknown as Dict), {
              statsTips: STAT_TIPS_AR,
            } as unknown as Dict),
          );
        })
        .catch((err: unknown) => callback(err instanceof Error ? err : new Error(String(err)), null));
      return;
    }
    if (language === "en") {
      void Promise.all([import("./en"), import("./gen/en"), import("./stats-tips")])
        .then(([{ en }, { genEn }, { STAT_TIPS_EN }]) => {
          callback(
            null,
            deepMerge(deepMerge(en as unknown as Dict, genEn as unknown as Dict), {
              statsTips: STAT_TIPS_EN,
            } as unknown as Dict),
          );
        })
        .catch((err: unknown) => callback(err instanceof Error ? err : new Error(String(err)), null));
      return;
    }
    // Unknown language — let i18next fall back to `fallbackLng` (fr).
    callback(new Error(`lazyLocaleBackend: no dictionary for "${language}"`), null);
  },
};

void i18next
  .use(lazyLocaleBackend)
  .use(initReactI18next)
  .init({
    // T-583: only FR is bundled. `partialBundledLanguages: true` tells
    // i18next the remaining supportedLngs arrive through the backend.
    resources: {
      // T-447 (UI-325): the glossary tree is namespaced under `statsTips`
      // (NOT merged at the root — its top-level group names live inside the
      // namespace so they can never collide with the base dictionary's).
      fr: {
        translation: deepMerge(deepMerge(fr as unknown as Dict, genFr as unknown as Dict), {
          statsTips: STAT_TIPS_FR,
        } as unknown as Dict),
      },
    },
    partialBundledLanguages: true,
    lng: "fr",
    fallbackLng: "fr",
    supportedLngs: ["fr", "ar", "en"],
    interpolation: { escapeValue: false },
    returnNull: false,
  });

export default i18next;
